// Merges the dated content packs (js/content_packs.js, generated by tools/content_packs.py)
// into the existing banks at load time. Additive and idempotent; a pack whose "released" date
// is still in the future is skipped. Mirrors apply_content_packs() in kids_exercise_app.py.
(function applyContentPacks() {
  if (typeof CONTENT_PACKS === "undefined") return;
  const today = new Date().toISOString().slice(0, 10);
  const templateBanks = { add: ADD_TEMPLATES, sub: SUB_TEMPLATES, mul: MUL_TEMPLATES, div: DIV_TEMPLATES };

  for (const pack of CONTENT_PACKS) {
    if ((pack.released || "") > today) continue;

    for (const [age, passages] of Object.entries(pack.reading_passages || {})) {
      const bank = APP_DATA.READING_PASSAGES[age];
      const have = new Set(bank.map((p) => p.text));
      for (const p of passages) if (!have.has(p.text)) { bank.push(p); have.add(p.text); }
    }

    // Fixed Central Idea stories join the procedural story shapes in one pool (see centralIdeaQ).
    APP_DATA.CENTRAL_IDEA_STORIES = APP_DATA.CENTRAL_IDEA_STORIES || { 0: [], 1: [], 2: [] };
    for (const [age, stories] of Object.entries(pack.central_idea_stories || {})) {
      const bank = APP_DATA.CENTRAL_IDEA_STORIES[age];
      const have = new Set(bank.map((s) => s.text));
      for (const s of stories) if (!have.has(s.text)) { bank.push(s); have.add(s.text); }
    }

    for (const [label, easy, hard] of [
      ["synonyms", APP_DATA.SYNONYMS, APP_DATA.SYNONYMS_HARD],
      ["antonyms", APP_DATA.ANTONYMS, APP_DATA.ANTONYMS_HARD],
    ]) {
      for (const [tier, bank] of [["easy", easy], ["hard", hard]]) {
        for (const [word, other] of Object.entries((pack[label] || {})[tier] || {})) {
          if (!(word in easy) && !(word in hard)) bank[word] = other;
        }
      }
    }

    for (const [tier, bank] of [["easy", APP_DATA.RHYME_SETS], ["hard", APP_DATA.RHYME_SETS_HARD]]) {
      const heads = new Set([...APP_DATA.RHYME_SETS, ...APP_DATA.RHYME_SETS_HARD].map((g) => g[0]));
      for (const group of (pack.rhymes || {})[tier] || []) {
        if (!heads.has(group[0])) { bank.push(group.slice()); heads.add(group[0]); }
      }
    }

    const haveAnalogies = new Set(APP_DATA.ANALOGY_PAIRS.map((t) => `${t[0]}|${t[2]}`));
    for (const t of pack.analogies || []) {
      const key = `${t[0]}|${t[2]}`;
      if (!haveAnalogies.has(key)) { APP_DATA.ANALOGY_PAIRS.push(t.slice()); haveAnalogies.add(key); }
    }

    for (const [op, templates] of Object.entries(pack.word_problem_templates || {})) {
      const bank = templateBanks[op];
      if (!bank) continue;
      for (const t of templates) if (!bank.includes(t)) bank.push(t);
    }

    // NYS Grade 3 style math banks (see generators/math_nys.js): graph themes, real-world masses
    // and volumes for estimating, two-step story templates, and time-problem activities.
    const mb = pack.math_banks;
    if (mb && typeof NYS_GRAPH_SETS !== "undefined") {
      const haveThemes = new Set(NYS_GRAPH_SETS.map((s) => s[0]));
      for (const g of mb.graph_sets || []) {
        if (!haveThemes.has(g.theme)) { NYS_GRAPH_SETS.push([g.theme, g.categories.slice(), g.noun]); haveThemes.add(g.theme); }
      }
      const haveMass = new Set(NYS_MASS_ITEMS.map((m) => m[0]));
      for (const m of mb.mass_items || []) {
        if (!haveMass.has(m.item)) { NYS_MASS_ITEMS.push([m.item, m.value, m.unit]); haveMass.add(m.item); }
      }
      const haveLiquid = new Set(NYS_LIQUID_ITEMS.map((m) => m[0]));
      for (const m of mb.liquid_items || []) {
        if (!haveLiquid.has(m.item)) { NYS_LIQUID_ITEMS.push([m.item, m.liters]); haveLiquid.add(m.item); }
      }
      const haveStories = new Set(NYS_STORIES_BUILTIN.concat(NYS_STORIES_EXTRA).map((s) => s.text));
      for (const s of mb.two_step_stories || []) {
        if (!haveStories.has(s.text)) { NYS_STORIES_EXTRA.push({ form: s.form, text: s.text }); haveStories.add(s.text); }
      }
      for (const a of mb.time_activities || []) if (!NYS_TIME_ACTIVITIES.includes(a)) NYS_TIME_ACTIVITIES.push(a);
    }
  }
})();
